from itertools import permutations
for p in permutations(range(5)):
    if p[2]!=3: continue
    vecs=set()
    ok=True
    for i in range(5):
        for j in range(i+1,5):
            v=(j-i, p[j]-p[i])
            if v in vecs: ok=False; break
            vecs.add(v)
        if not ok: break
    if ok:
        print(p)
